    "answer": "Basic HTML form controls include:\n1. Text inputs (text boxes, password boxes)\n2. Buttons (Submit, Reset)\n3. Checkboxes and Radio buttons\n4. Select menus (Drop-down lists) and Textarea.",
    "answerTamil": "அடிப்படை HTML படிவக் கட்டுப்பாடுகள்:\n1. உரை உள்ளீடுகள் (Text box, Password)\n2. பொத்தான்கள் (Submit, Reset)\n3. தேர்வுப் பெட்டிகள் மற்றும் ரேடியோ பொத்தான்கள்\n4. கீழ்தோன்று பட்டியல் (Select dropdown) மற்றும் உரைப் பகுதி (Textarea).",
