    "answerTamil": "Wi-Fi-ன் நன்மைகள்:\n1. கம்பிகள் இல்லா இயக்கம் மற்றும் எளிதான இணைப்பு.\n2. எளிய நிறுவல் முறை மற்றும் குறைவான செலவு.\n3. பல சாதனங்களை ஒரே நேரத்தில் இணைக்கும் வசதி.",
